    minutes: ${3:1}

- trigger: numeric_state
  entity_id: ${1:sensor.example}
  above: ${2:80}

- condition: state
  entity_id: ${1:binary_sensor.example}
  state: ${2:on}

- condition: numeric_state
  entity_id: ${1:sensor.example}
  above: ${2:80}

- condition: and
