    - condition: state
      entity_id: ${1:binary_sensor.example}
      state: ${2:on}

- action: ${1:light.turn_on}
  target:
    entity_id: ${2:light.example}
  data:
    ${3:brightness_pct}: ${4:100}

- choose:
    - conditions:
        - condition: state
          entity_id: ${1:binary_sensor.example}
          state: ${2:on}
      sequence:
        - action: ${3:light.turn_on}
          target:
            entity_id: ${4:light.example}
  default:
    - action: ${5:light.turn_off}
      target:
        entity_id: ${6:light.example}

- if:
    - condition: state
      entity_id: ${1:binary_sensor.example}
      state: ${2:on}
  then:
    - action: ${3:light.turn_on}
      target:
        entity_id: ${4:light.example}
  else:
    - action: ${5:light.turn_off}
      target:
        entity_id: ${6:light.example}

- wait_for_trigger:
    - trigger: state
      entity_id: ${1:binary_sensor.example}
      to: ${2:on}
  timeout:
    minutes: ${3:5}
  continue_on_timeout: ${4:false}

